$ErrorActionPreference='Stop';$temp=Join-Path ([IO.Path]::GetTempPath()) ('exp121-log-'+[guid]::NewGuid());New-Item -ItemType Directory -Path $temp|Out-Null
try{$stdout=Join-Path $temp 'stdout.log';$stderr=Join-Path $temp 'stderr.log';$p=Start-Process cmd.exe -ArgumentList @('/c','echo out & echo err 1>&2 & exit /b 0') -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru -Wait;if($p.ExitCode-ne0 -or (Get-Item $stdout).Length-eq0 -or (Get-Item $stderr).Length-eq0){throw 'normal-stderr fixture failed'};$q=Start-Process cmd.exe -ArgumentList @('/c','echo err 1>&2 & exit /b 1') -RedirectStandardOutput (Join-Path $temp 'bad-out.log') -RedirectStandardError (Join-Path $temp 'bad-err.log') -PassThru -Wait;if($q.ExitCode-ne1 -or (Get-Item (Join-Path $temp 'bad-err.log')).Length-eq0){throw 'non-zero fixture failed'};[ordered]@{normalStderr='PASSED';nonZero='APPLICATION_LOG_CAPTURE_FAILED'}|ConvertTo-Json}finally{Remove-Item -LiteralPath $temp -Recurse -Force}
